 Q,R,X=s;n=len(Q);Q=list(Q)
 if c==0:
  if n>=3:return
  t=(X+4+n)%5;Q+=[t];R=(R+1)%4;X=(X*2+t+R)%89
 elif c==1:
  if n<=1:return
  q=Q.pop(0);Q+=[q];R=(R+n)%4;X=(X+4*q+n+R)%89
 else:
  if n<=0:return
  q=Q.pop(0);R=(R+q+1)%4;X=(X*2+7*q+n+R)%89
 return (tuple(Q),R,X)
D={( (2,1),1,5):\"\"}
for i in range(10):
 print(i,len(D),\"target\",((3,4),0,15) in D)
 if i==9:break
 E={}
 for s,path in D.items():
  for c in range(3):
   t=f(s,c)
   if t:E.setdefault(t,path+\" LRE\"[c*2:c*2+1])
 D=E'"

